// Generated by scripts/generate-framework-skills.mjs. Do not edit directly.
export const FRAMEWORK_SKILL_CONTENT = {
  "astro": "---\nname: astro\ndescription: Generate and edit Astro applications using file-based pages, layouts, content, server endpoints, islands, view transitions, and adapter-driven rendering. Use for framework id astro and content-focused or multi-framework sites.\n---\n\n# Astro\n\nShip HTML by default and add client JavaScript only where interaction requires an island.\n\n## Project contract\n\n- Declare `astro` and only the renderer/integration packages actually used.\n- Put routable pages and endpoints in `src/pages`, reusable shells in `src/layouts`, components in `src/components`, and public assets in `public`.\n- Keep project configuration in `astro.config.*` and environment types in the framework's conventional location.\n- Use `.astro` components for server-rendered composition. Add React, Vue, Svelte, Solid, or other islands only with the matching integration.\n- Choose `client:*` hydration directives deliberately; do not hydrate static presentation.\n- Select static or on-demand rendering and a deployment adapter according to product requirements.\n\n## Editing rules\n\n- Keep secrets in server execution and never pass them through island props or public environment variables.\n- Add every imported package and avoid mixing renderer syntax inside `.astro` templates.\n- Preserve content collection schemas and generated types.\n\n## Verification\n\nRun `astro check` when configured and the production build. Inspect output for accidental client bundles and confirm endpoint/rendering behavior under the selected adapter.\n",
  "farmjs": "---\nname: farmjs\ndescription: Generate and edit current Farm.js applications using app-directory routing, typed server and browser APIs, renderer adapters, integrations, storage, i18n, cron, and portable deployment targets. Use for every Farm.js project and iteration.\n---\n\n# Farm.js\n\nPreserve the existing Farm.js project contract. Do not substitute FarmFE, `@farmfe/*`, or another framework. Treat the checked-in manifest, `farm.config.ts`, route tree, and locked files as authoritative.\n\n## Project contract\n\n- Keep every published `@farm.js/*` package on the same release channel and compatible version.\n- Configure the app in `farm.config.ts` with `defineConfig` from `@farm.js/core`.\n- Put routes under `src/app`: `layout`, `page`, nested segments, and `api/**/route`.\n- Return application UI or a fragment from the root layout. Farm.js owns the `<html>`, `<head>`, and `<body>` document shell.\n- Add `\"use client\"` only to components that require browser APIs, state, effects, client bindings, or event handlers.\n- Use the existing package manager. New Viby workspaces use `pnpm`.\n- Use Farm's built-in Tailwind integration when Tailwind is selected. Do not add PostCSS or `@tailwindcss/postcss` unless the project explicitly requires it.\n- Preserve locked configuration and compatibility declarations supplied by the host.\n\n## Renderers and routes\n\nReact is the default renderer. Farm.js also supports Preact, Solid, Vue, and Svelte through renderer adapters. Preserve the selected renderer and use its native component format and bindings; never mix renderer formats in one route tree.\n\nRouting conventions include:\n\n- `src/app/page.tsx` maps to `/`.\n- `src/app/about/page.tsx` maps to `/about`.\n- `src/app/users/[id]/page.tsx` maps to a dynamic route.\n- `[...slug]` and `[[...slug]]` create required and optional catch-all routes.\n- Route groups do not appear in URLs; named slots and intercepted routes are supported.\n- `loading`, `error`, and `not-found` files define route boundaries.\n- Use Farm's `PageProps`, `LayoutProps`, typed `Link href`, and generated `src/farm.d.ts` declarations.\n\n## Configuration\n\nUse current documented fields rather than inventing framework APIs. Common config surfaces include:\n\n- `renderer`, `srcDir`, `api`, and `experimental.serverComponents`\n- `integrations`, top-level `auth`, `storage.mounts`, and `migrations`\n- `i18n`, `cron`, `docs`, `md`, `mdx`, and `openapi`\n- `deploy.target`, `deploy.preset`, and deployment output\n- `routeRules`, `security`, `serverActions`, `images`, and `performance`\n- `plugins`, `redirects()`, `headers()`, `rewrites()`, and `vite`\n\nPrefer `deploy.target` for first-class targets. Use `deploy.preset` only for explicit Nitro pass-through; a preset overrides a target. Keep deploy output separate from immutable raw source.\n\n## Data and server behavior\n\n- API routes live under `src/app/api/**/route.ts`.\n- Prefer `createEndpoint` from `@farm.js/core/api` for validated, generated caller types; standard HTTP method exports remain valid.\n- Use `createAPIClient` from `@farm.js/core/client` for application routes.\n- Use `createIntegrations<AppIntegrations>()` for configured integration namespaces and export the registry type.\n- Use `createServerFn` for typed mutations and `createServerQuery` for typed reads when the project has the documented server-function transform.\n- Use `loadRouteParams`, `loadSearchParams`, and query parsers on the server; use `useQueryState` or `useQueryStates` for React client URL state.\n- Keep secrets and provider SDKs in server-only modules.\n\nFarm supports typed HTTP queries, multipart uploads, streamed results, caching, invalidation, retries, optimistic updates, and structured server-query refresh. Follow the closest current project pattern instead of approximating another framework's API.\n\n## Integrations, auth, storage, and jobs\n\n- New provider code uses dedicated packages such as `@farm.js/stripe`, `@farm.js/clerk`, `@farm.js/resend`, and `@farm.js/jobs`.\n- Older `@farm.js/integrations/*` imports are compatibility paths, not the preferred surface for new work.\n- The integration registry key is the client namespace, such as `billing` becoming `api.billing`.\n- Use `defineIntegration`, typed endpoints, lifecycle hooks, middleware, providers, and validated config for custom integrations.\n- Use top-level `auth` with `@farm.js/auth` for built-in email/password sessions. Do not combine top-level auth with `integrations.auth`.\n- Use `@farm.js/core/storage` mounts for provider-neutral storage rather than embedding provider calls throughout the UI.\n- Use config-plus-route cron for portable schedules; handlers must be idempotent. Use a jobs integration for durable retries, queues, steps, or long-running work.\n\nCurrent integration families include AI, billing, email, jobs, auth, data, agents, security, and custom app-owned provider instances. Add every imported adapter to the manifest.\n\n## Product capabilities\n\nFarm.js has first-class configuration for internationalization, typed ICU catalogs, themes, fonts, image policy, documentation/MDX, OpenAPI, route caching and rendering modes, CSP, observability, runtime events, migrations, and multiple deployment targets. Reuse those primitives when the request needs them instead of introducing parallel configuration systems.\n\n## Verification\n\n1. Inspect `package.json`, the lockfile, `farm.config.ts`, `src/farm.d.ts`, and the route tree.\n2. Preserve the renderer, package manager, source layout, config, and deployment contract.\n3. Add every imported package to the manifest and keep React peer dependencies compatible.\n4. Prefer framework APIs from `@farm.js/core` and dedicated `@farm.js/*` adapters over invented helpers.\n5. Keep generated source readable; do not compress JSX, CSS, handlers, or data into dense one-line output.\n6. Run the project's declared generate, typecheck, and build scripts. Use `farm doctor`, `farm explain`, or `farm deploy --plan` when the resolved runtime matters.\n7. For remote sandbox previews, use `farm dev --host 0.0.0.0 --port <port>` and reuse the prepared workspace. A local-only preview can omit `--host`. Do not reinstall dependencies.\n\nNever modify a locked file, expose a secret to client code, mix renderers, combine incompatible auth modes, or silently replace the framework.\n",
  "nextjs": "---\nname: nextjs\ndescription: Generate and edit Next.js applications using the App Router, React Server and Client Components, route handlers, layouts, metadata, and Next.js build conventions. Use for framework id nextjs and existing Next.js projects.\n---\n\n# Next.js\n\nUse the App Router for new projects unless the imported source already uses the Pages Router.\n\n## Project contract\n\n- Declare compatible `next`, `react`, and `react-dom` dependencies.\n- Put routes in `app/` or `src/app/`. Provide a required root `layout.tsx` containing `<html>` and `<body>` and a `page.tsx` for `/`.\n- Use special files such as `loading.tsx`, `error.tsx`, `not-found.tsx`, and `route.ts` according to their framework roles.\n- Keep components server-rendered by default. Add `\"use client\"` only where hooks, browser APIs, mutable state, or event handlers require it.\n- Use route handlers for HTTP APIs and server functions/actions for trusted application mutations. Validate inputs and authorize on the server.\n- Keep static assets in `public/` and framework configuration in `next.config.*`.\n\n## Editing rules\n\n- Do not mix Pages Router and App Router conventions in a new tree.\n- Do not expose secrets through client components or public environment-variable prefixes.\n- Preserve generated type files and existing bundler choices.\n- Add every imported package and verify its React peer range.\n\n## Verification\n\nUse the manifest's scripts. A conventional project supports `next dev`, `next build`, and `next start`; typecheck separately when the project defines it.\n",
  "nuxt": "---\nname: nuxt\ndescription: Generate and edit full-stack Nuxt applications using Vue, filesystem pages, layouts, composables, Nitro server routes, runtime configuration, and deployment presets. Use for framework id nuxt and SSR or server-enabled Vue products.\n---\n\n# Nuxt\n\nFollow the installed Nuxt major version and preserve its directory convention. For a new current project, use the `app/` application directory and `server/` for Nitro code.\n\n## Project contract\n\n- Declare `nuxt` and `vue` with compatible versions and configure the project in `nuxt.config.ts`.\n- Place UI routes in `app/pages`, shared layouts in `app/layouts`, components in `app/components`, and composables in `app/composables` for current projects. Preserve root-level Nuxt 3 layout when importing an existing project.\n- Put HTTP handlers in `server/api` or `server/routes` and code shared by app and server in `shared`.\n- Put unchanged public assets in `public`; put processed assets in the application assets directory.\n- Store public runtime values under `runtimeConfig.public` and keep secrets in private runtime configuration.\n\n## Editing rules\n\n- Respect Nuxt auto-imports without inventing unavailable modules.\n- Do not expose secrets through app config or public runtime config.\n- Keep provider behavior in Nitro/deployment configuration and add every imported module to the manifest.\n\n## Verification\n\nRun Nuxt's generated type preparation/typecheck when declared, then the production build. Verify the selected Nitro preset against the requested deployment target.\n",
  "react-router": "---\nname: react-router\ndescription: Generate and edit React Router Framework Mode applications using route configuration, route modules, loaders, actions, middleware, pending UI, SSR, and provider adapters. Use for framework id react-router rather than declarative router-only SPAs.\n---\n\n# React Router Framework Mode\n\nUse Framework Mode and preserve its route-module contract.\n\n## Project contract\n\n- Declare compatible `react-router`, React, framework development, and deployment adapter packages.\n- Keep the document shell in `app/root.tsx`, route configuration in `app/routes.ts`, and framework options in `react-router.config.ts`.\n- Implement route modules with typed loader, action, metadata, headers, error-boundary, and component exports as required.\n- Use loaders for reads, actions for mutations, `<Form>` for progressive enhancement, and fetchers for concurrent non-navigation interactions.\n- Keep `.server` modules out of client graphs and `.client` modules out of server rendering.\n- Preserve entry files and provider presets when the template supplies them.\n\n## Editing rules\n\n- Do not mix declarative `<Routes>` setup with a Framework Mode project unless integrating an explicit nested use case.\n- Use generated route types rather than recreating parameter types manually.\n- Add every imported package and keep authorization inside loaders/actions.\n\n## Verification\n\nRun framework type generation, typecheck, and the production build. Exercise loaders, actions, error boundaries, and the selected deployment adapter.\n",
  "solid": "---\nname: solid\ndescription: Generate and edit client-side Solid applications using fine-grained reactivity, typed JSX, Vite, Solid control-flow components, and accessible browser UI. Use for framework id solid when SolidStart server features are not required.\n---\n\n# Solid\n\nBuild a client-side Solid application. Use the separate SolidStart target for filesystem routes, server functions, APIs, or SSR.\n\n## Project contract\n\n- Declare compatible `solid-js`, `vite`, and Solid Vite plugin dependencies.\n- Keep the browser entry in `src/index.tsx` or the existing entry and mount with Solid's `render` API.\n- Use Solid primitives such as signals, memos, resources, and effects. Do not write React hooks or destructure reactive props in ways that lose tracking.\n- Prefer Solid control-flow components for reactive branching and lists where they improve correctness.\n- Keep styles and design tokens explicit and preserve the existing Vite plugin chain.\n\n## Editing rules\n\n- Do not add SolidStart routing to a plain Solid target.\n- Add every imported package and preserve JSX compiler settings.\n- Use semantic HTML and accessible interactions.\n\n## Verification\n\nRun the declared typecheck and `vite build`. Test state updates, conditional rendering, and list identity rather than assuming React behavior.\n",
  "solidstart": "---\nname: solidstart\ndescription: Generate and edit SolidStart applications using filesystem routes, Solid reactivity, server functions, API routes, Vite configuration, and Nitro deployment. Use for framework id solidstart and full-stack Solid projects.\n---\n\n# SolidStart\n\nFollow the installed SolidStart major version. Preserve an imported v1 layout; use current v2 conventions for a new project.\n\n## Project contract\n\n- Declare compatible SolidStart, Solid, router, Vite, and Nitro packages required by the selected template.\n- Put routes in `src/routes`; use default exports for UI routes and HTTP method exports for API routes.\n- Keep the document/app shell in `src/app.tsx` and preserve framework entry files when the template supplies them.\n- Configure current projects in `vite.config.ts` with the SolidStart and Nitro plugins expected by the installed version.\n- Use Solid reactive primitives, not React hooks. Keep server-only work behind SolidStart server functions or API routes and validate inputs.\n\n## Editing rules\n\n- Do not mix v1 Vinxi configuration into a v2 project or migrate an imported project implicitly.\n- Preserve filesystem route naming and add every imported dependency.\n- Keep secrets server-only and deployment behavior in Nitro configuration.\n\n## Verification\n\nRun the project's typecheck and build scripts, then start the production output or preview contract supplied by the selected Nitro preset.\n",
  "svelte": "---\nname: svelte\ndescription: Generate and edit client-side Svelte applications with typed single-file components, Vite, scoped styles, accessible events, and Svelte state conventions. Use for framework id svelte when a full SvelteKit server is not requested.\n---\n\n# Svelte\n\nBuild a Svelte client application. Use the separate SvelteKit target when file-based routing, server loading, form actions, or server endpoints are required.\n\n## Project contract\n\n- Declare `svelte`, `vite`, and the official Svelte Vite plugin with compatible versions.\n- Keep the browser entry in `src/main.ts` and the application shell in `src/App.svelte` unless the imported project establishes another layout.\n- Write typed `.svelte` components and use the state/props conventions supported by the installed Svelte version.\n- Prefer component composition and scoped styles. Keep global tokens and resets in an explicitly imported global stylesheet.\n- Use semantic HTML and native accessible interactions; do not attach click handlers to non-interactive elements without keyboard behavior and roles.\n\n## Editing rules\n\n- Do not add SvelteKit route conventions to a plain Svelte project.\n- Do not generate React hooks, JSX-only patterns, or Vue directives.\n- Add every imported package and preserve the existing Vite plugin chain.\n\n## Verification\n\nRun the declared check/typecheck and build scripts. A conventional Vite-backed project uses `vite` for development and `vite build` for production.\n",
  "sveltekit": "---\nname: sveltekit\ndescription: Generate and edit SvelteKit applications using filesystem routes, layouts, load functions, form actions, server endpoints, adapters, and server-only module boundaries. Use for framework id sveltekit and full-stack Svelte projects.\n---\n\n# SvelteKit\n\nPreserve SvelteKit's filesystem routing and server/client boundaries.\n\n## Project contract\n\n- Declare compatible `@sveltejs/kit`, `svelte`, `vite`, and adapter packages.\n- Put routes in `src/routes` using `+page.svelte`, `+layout.svelte`, `+page.ts`, `+page.server.ts`, and `+server.ts` according to responsibility.\n- Put reusable code in `src/lib`; keep secrets and privileged helpers under `src/lib/server`.\n- Keep the SvelteKit Vite plugin in `vite.config.*`, framework configuration in `svelte.config.*`, and deployment behavior in the selected adapter.\n- Use load functions for route data and form actions for progressively enhanced mutations. Validate and authorize server operations.\n- Store unprocessed public assets in `static/`.\n\n## Editing rules\n\n- Never import server-only modules into browser code.\n- Preserve the generated `.svelte-kit` TypeScript base configuration rather than copying generated output into source.\n- Follow the syntax supported by the installed Svelte version and add every imported dependency.\n\n## Verification\n\nRun the project's check and build scripts. Confirm the chosen adapter matches the deployment target and that no private environment value enters client output.\n",
  "tanstack-start": "---\nname: tanstack-start\ndescription: Generate and edit TanStack Start React applications using TanStack Router file routes, loaders, validated search params, server functions, middleware, SSR, and runtime-neutral deployment output. Use for framework id tanstack-start.\n---\n\n# TanStack Start\n\nKeep TanStack Router as the application contract and TanStack Start as the server/rendering layer.\n\n## Project contract\n\n- Declare compatible TanStack Start, TanStack Router, React, and build-tool dependencies.\n- Keep routes in `src/routes`, the root document route in `src/routes/__root.tsx`, and router creation in `src/router.tsx`.\n- Treat `src/routeTree.gen.ts` as generated output; never hand-edit it.\n- Use route loaders, validated search parameters, pending/error boundaries, and typed links instead of ad hoc routing state.\n- Use `createServerFn` for typed app-internal server calls and server routes for external HTTP consumers. Keep privileged helpers in server-only modules.\n- Preserve the selected Vite or Rsbuild configuration and deployment adapter.\n\n## Editing rules\n\n- Export a fresh router from the template's router factory and keep required root document components/scripts.\n- Add every imported package and keep React peer dependencies compatible.\n- Do not copy App Router or React Router route conventions into this tree.\n\n## Verification\n\nRun route generation, typecheck, tests, and the production build using the manifest's scripts. Never commit a stale generated route tree.\n",
  "vite": "---\nname: vite\ndescription: Generate and edit Vite applications while preserving the selected UI renderer, TypeScript setup, plugin chain, environment boundaries, static assets, and production build contract. Use for framework id vite when no meta-framework is selected.\n---\n\n# Vite\n\nTreat Vite as the build/runtime target, not as a UI framework. Determine the renderer from the prompt, existing source, or declared dependencies.\n\n## Project contract\n\n- Keep `index.html` as the browser entry and application source under `src` unless the imported project establishes another structure.\n- Configure plugins in `vite.config.*` and install the official plugin for the selected renderer.\n- Use `import.meta.env` only for values intended for the browser and honor the project's public environment prefix.\n- Put copied static assets in `public`; import processed assets from source.\n- Keep aliases synchronized between Vite and TypeScript.\n\n## Editing rules\n\n- Do not silently add React, Vue, Svelte, Solid, or another renderer when the request is ambiguous; return a typed question when that choice affects the project.\n- Do not add meta-framework filesystem routes or server APIs to a plain Vite target.\n- Add every imported package and preserve the existing plugin order.\n\n## Verification\n\nRun the selected renderer's typecheck plus `vite build`. Use the manifest's preview command to verify base paths, asset URLs, and client-side routing fallbacks.\n",
  "vue": "---\nname: vue\ndescription: Generate and edit typed Vue applications with Vite, Vue single-file components, Composition API, scoped styles, and optional Vue Router or Pinia integrations. Use for framework id vue when Nuxt server features are not required.\n---\n\n# Vue\n\nBuild a Vue client application. Use the separate Nuxt target for filesystem routing, SSR, server APIs, or Nitro deployment.\n\n## Project contract\n\n- Declare compatible `vue`, `vite`, and `@vitejs/plugin-vue` dependencies.\n- Keep the entry in `src/main.ts`, the root in `src/App.vue`, and feature components under `src/components` unless the imported source establishes another structure.\n- Prefer typed `<script setup lang=\"ts\">` single-file components and the Composition API.\n- Keep component styles scoped when local and import shared design tokens or resets once at the application entry.\n- Add Vue Router or Pinia only when the prompt or existing source needs them; configure them through their normal app plugins.\n\n## Editing rules\n\n- Do not generate React hooks, Svelte runes, or Nuxt auto-import assumptions.\n- Preserve the existing Vite plugin chain and TypeScript aliases.\n- Add every imported package and avoid mutating props directly.\n\n## Verification\n\nRun the declared typecheck and production build. Conventional scripts use `vite`, `vue-tsc`, and `vite build`.\n"
} as const;
